 "content": "def transform(grid):
    """Add an 8 marker along the outer edge of the region on the far side of the 2 guide."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The guide is a full uniform 2 row or column.
    guides = [(r, 'h') for r in range(h) if all(v == 2 for v in g[r])]
    guides += [(c, 'v') for c in range(w) if all(g[r][c] == 2 for r in range(h))]
    if not guides:
        return g
    idx, orient = guides[0]
    if orient == 'h':
        # Mark the outer boundary row of the nonempty region below the guide.
        # Demos show added line along that region's far horizontal edge.
        rows = [r for r in range(idx + 1, h) if any(v not in (2, 9) for v in g[r])]
        if rows:
            r = max(rows) + 1 if max(rows) + 1 < h and all(v == 9 for v in g[max(rows)+1]) else max(rows)
            for c in range(w):
                if g[r][c] == 9:
                    g[r][c] = 8
    else:
        # Vertical guide: added line at the far outer edge of the active region.
        cols = [c for c in range(idx) if any(g[r][c] not in (2, 3) for r in range(h))]
        if cols:
            c = min(cols)
            for r in range(h):
                if g[r][c] == 3:
                    g[r][c] = 8
    return g

if __name__ == '__main__':
    import json
    grid = [[6]*28 for _ in range(11)]
    grid[4][26] = 9
    grid[5] = [2]*28
    print(json.dumps(transform(grid)))
